725	    if(ret == TIMER_DROP_AUDIO_DATA)
726	    {
727	        AudioDecCompReleasePcmData(p->pDecComp, threadCtx->nPcmDataLen);
728	        //* post a render message to continue the rendering job after message processed.
729	        BaseCompContinue(&p->base);
730	        return -1;
731	    }
732	    else if(ret == TIMER_NEED_NOTIFY_AGAIN)
733	    {
734	        /* waiting process for first frame sync with video is
735	         * broken by a new message to player, so the player tell us
736	         * to notify again later.
