1250	static int dm_sound_write(SoundCtrl *s, void *data, int size)
1251	{
1252	    dm_sound_ctrl_t *sc = (dm_sound_ctrl_t *)s;
1253	    snd_pcm_sframes_t frames;
1254	    /* S24_LE uses a 32-bit physical container (aw-tiny-alsa
1255	     * snd_pcm_format_physical_width(S24_LE)=32), so frame bytes must be
1256	     * derived from the physical width, not the logical bit depth. */
1257	    int phys_bits = (sc->bits >= 32) ? 32 : (sc->bits >= 24) ? 32 : 16;
1258	    int bps = (phys_bits / 8) * sc->channels;
1259	
1260	    if (!sc->handle || !data || bps <= 0)
1261	        return 0;
1262	    frames = size / bps;
1263	    if (frames <= 0)
1264	        return 0;
1265	    {
1266	        int wr = (int)snd_vela_pcm_writei(sc->handle, data, frames);
1267	        static int dbg_cnt;
1268	        if ((++dbg_cnt % 20) == 1)   /* 每 20 次打印一次，防刷屏 */
1269	            printf("[music] writei size=%d bits=%d ch=%d frames=%d wr=%d\n",
1270	                   size, sc->bits, sc->channels, (int)frames, wr);
1271	        /* -EPIPE = underrun: the reference (sunxi_alsa xrun) recovers by
1272	         * re-prepare so the substream restarts on the next write. Without
1273	         * this, once the decoder is briefly slow the codec stays stuck. */
1274	        if (wr == -EPIPE)
1275	        {
1276	            if ((++dbg_cnt % 20) == 1)
1277	                printf("[music] underrun, re-prepare\n");
1278	            snd_vela_pcm_prepare(sc->handle);
1279	            return 0;
1280	        }
1281	        return wr;
1282	    }
1283	}
