static int dm_sound_write(SoundCtrl *s, void *data, int size)
{
    dm_sound_ctrl_t *sc = (dm_sound_ctrl_t *)s;
    snd_pcm_sframes_t frames;
    /* S24_LE uses a 32-bit physical container (aw-tiny-alsa
     * snd_pcm_format_physical_width(S24_LE)=32), so frame bytes must be
     * derived from the physical width, not the logical bit depth. */
    int phys_bits = (sc->bits >= 32) ? 32 : (sc->bits >= 24) ? 32 : 16;
    int bps = (phys_bits / 8) * sc->channels;

    if (!sc->handle || !data || bps <= 0)
        return 0;
    frames = size / bps;
    if (frames <= 0)
        return 0;
    {
        int wr = (int)snd_vela_pcm_writei(sc->handle, data, frames);
        static int dbg_cnt;
        if ((++dbg_cnt % 20) == 1)   /* 每 20 次打印一次，防刷屏 */
            printf("[music] writei size=%d bits=%d ch=%d frames=%d wr=%d\n",
                   size, sc->bits, sc->channels, (int)frames, wr);
        /* -EPIPE = underrun: the reference (sunxi_alsa xrun) recovers by
         * re-prepare so the substream restarts on the next write. Without
         * this, once the decoder is briefly slow the codec stays stuck. */
        if (wr == -EPIPE)
        {
            if ((++dbg_cnt % 20) == 1)
                printf("[music] underrun, re-prepare\n");
            snd_vela_pcm_prepare(sc->handle);
            return 0;
        }
        return wr;
    }
}

